--- index.html
+++ index.html
@@ -23,4 +23,41 @@
 <div class="mobile-controls" id="joystick"><div class="joy-knob" id="knob"></div></div>
 <div class="help"><kbd>WASD</kbd> Hareket &nbsp; <kbd>Sol tık</kbd> Saldır &nbsp; <kbd>Q W E R</kbd> Yetenekler</div>
 <div class="overlay" id="overlay"><div class="modal"><div class="modal-mark">✦</div><h1>YILDIZYARIĞI</h1><div class="sub">KIRIK TAÇ VADİSİ · MOBA / RPG</div><p>Unutulmuş bir vadide beş kişilik takımının öncüsü ol. Koridoru it, kadim yaratıkları avla ve düşman kulesini yık. Her savaş seni biraz daha güçlendirir.</p><div class="controls"><span>WASD · Hareket</span><span>Sol tık · Saldır</span><span>Q W E R · Yetenek</span><span>F · Şifa iksiri</span></div><button class="play-btn" id="playBtn">VADİYE GİR</button><p class="modal-note">Tek oyunculu macera · Oyun otomatik kaydedilmez</p></div></div>
 <script>
+(()=>{'use strict';
+const canvas=document.getElementById('world'),ctx=canvas.getContext('2d'),mini=document.getElementById('mini'),mctx=mini.getContext('2d');
+const W=2400,H=1600, lane=[{x:210,y:1370},{x:520,y:1300},{x:790,y:1110},{x:1030,y:925},{x:1320,y:770},{x:1550,y:590},{x:1810,y:440},{x:2180,y:220}];
+let vw=0,vh=0,dpr=1,camera={x:390,y:1200},last=0,gameTime=0,started=false,paused=false,gameOver=false,mouse={x:0,y:0,wx:0,wy:0},keys={},entities=[],projectiles=[],particles=[],decals=[],waveTimer=5,spawnEnemy=4,tower={x:1855,y:408,hp:1500,max:1500,team:'red',dead:false},core={x:2180,y:220,hp:2600,max:2600,dead:false},kills=0,deaths=0,assists=0,allyScore=0,enemyScore=0,questKills=0,gold=250,level=1,xp=0,xpNeed=100,potions=2,autoTarget=null,attackTimer=0,cast={q:0,w:0,e:0,r:0},player={x:335,y:1325,hp:620,max:620,mana:300,maxMana:300,speed:210,damage:47,range:190,radius:16,shield:0,alive:true,respawn:0,heading:0,attackAnim:0};
+const clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),rand=(a,b)=>a+Math.random()*(b-a),$=id=>document.getElementById(id);
+function resize(){dpr=Math.min(devicePixelRatio||1,2);vw=innerWidth;vh=innerHeight;canvas.width=Math.floor(vw*dpr);canvas.height=Math.floor(vh*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);mini.width=296;mini.height=210}addEventListener('resize',resize);resize();
+function lanePoint(t){const f=t*(lane.length-1),i=Math.min(lane.length-2,Math.floor(f)),q=f-i;return{x:lane[i].x+(lane[i+1].x-lane[i].x)*q,y:lane[i].y+(lane[i+1].y-lane[i].y)*q}}
+function addEntity(o){entities.push({hp:o.max,hurt:0,attack:rand(.1,.8),...o})}
+function spawnMinion(team,t){const p=lanePoint(team==='blue'?0:1);addEntity({type:'minion',team,x:p.x+rand(-14,14),y:p.y+rand(-14,14),hp:180,max:180,damage:19,speed:team==='blue'?66:60,radius:10,range:105,level:1,worth:24,dead:false,progress:team==='blue'?0:1})}
+function wave(team){for(let i=0;i<3;i++)setTimeout(()=>{if(started&&!gameOver)spawnMinion(team,0)},i*480)}
+function spawnMob(x,y,type='shade'){addEntity({type,team:'neutral',x,y,hp:type==='golem'?470:250,max:type==='golem'?470:250,damage:type==='golem'?42:27,speed:type==='golem'?48:66,radius:type==='golem'?22:14,range:47,worth:type==='golem'?95:62,aggro:230,homeX:x,homeY:y,dead:false,attack:rand(.3,.9)})}
+function initWorld(){entities=[];projectiles=[];particles=[];decals=[];player.x=335;player.y=1325;player.hp=player.max=620;player.mana=player.maxMana=300;player.alive=true;player.shield=0;player.respawn=0;waveTimer=5;spawnEnemy=4;gameTime=0;kills=deaths=assists=allyScore=enemyScore=questKills=0;level=1;xp=0;xpNeed=100;gold=250;potions=2;tower.hp=tower.max;tower.dead=false;core.hp=core.max;core.dead=false;for(let i=0;i<5;i++){spawnMinion('blue',0);spawnMinion('red',0)}spawnMob(1150,480);spawnMob(1220,510);spawnMob(810,730);spawnMob(875,750);spawnMob(1540,960,'golem');spawnMob(1500,1010);spawnMob(520,870,'golem');spawnMob(575,900)}
+function pathStroke(c,width,color){c.beginPath();c.moveTo(lane[0].x,lane[0].y);for(let i=1;i<lane.length;i++)c.lineTo(lane[i].x,lane[i].y);c.lineWidth=width;c.lineCap='round';c.lineJoin='round';c.strokeStyle=color;c.stroke()}
+function drawGround(){ctx.fillStyle='#192e26';ctx.fillRect(0,0,W,H);
+// subtle grass mosaic
+for(let y=30;y<H;y+=64)for(let x=25;x<W;x+=70){const v=((x*7+y*13)%17);ctx.fillStyle=v<5?'#20372b':v<9?'#1b3229':'#1c3028';ctx.fillRect(x+(y%3)*6,y,42,37)}
+// river ribbon
+ctx.beginPath();ctx.moveTo(760,0);ctx.bezierCurveTo(900,230,610,420,820,650);ctx.bezierCurveTo(970,850,680,1060,880,1260);ctx.bezierCurveTo(1020,1410,850,1500,790,1600);ctx.lineTo(950,1600);ctx.bezierCurveTo(1050,1460,1170,1370,1030,1230);ctx.bezierCurveTo(850,1030,1140,850,970,620);ctx.bezierCurveTo(780,400,1070,220,900,0);ctx.closePath();ctx.fillStyle='#183f43';ctx.fill();ctx.strokeStyle='#4b77704c';ctx.lineWidth=6;ctx.stroke();
+// stone lane
+pathStroke(ctx,186,'#17231f');pathStroke(ctx,172,'#675f49');pathStroke(ctx,148,'#8b8060');pathStroke(ctx,4,'#c6af7970');
+// pavers and lane seams
+for(let t=.02;t<.99;t+=.022){const p=lanePoint(t),q=lanePoint(Math.min(.999,t+.002)),angle=Math.atan2(q.y-p.y,q.x-p.x);ctx.save();ctx.translate(p.x,p.y);ctx.rotate(angle);ctx.strokeStyle='#403e32';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-7,-69);ctx.lineTo(-7,69);ctx.stroke();ctx.restore()}
+// water glints
+for(let i=0;i<24;i++){let x=730+(i*79)%290,y=40+(i*137)%1480;if((x+y)%5>2){ctx.strokeStyle='#79b8a344';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+rand(8,28),y-3);ctx.stroke()}}
+// forest clusters, scattered rocks and flora
+for(let i=0;i<54;i++){const x=40+(i*173)%2300,y=28+(i*263)%1520;const onLane=lane.some(p=>Math.hypot(p.x-x,p.y-y)<135);if(onLane|| (x>720&&x<970&&y<1450))continue;drawTree(x,y, .75+((i*3)%6)*.09,i%4)}
+for(let i=0;i<66;i++){let x=(i*347+135)%W,y=(i*227+75)%H;if(lane.some(p=>Math.hypot(p.x-x,p.y-y)<110))continue;ctx.fillStyle=i%3?'#59614c':'#b59d64';ctx.globalAlpha=.55;ctx.beginPath();ctx.ellipse(x,y,rand(3,8),rand(2,5),rand(-1,1),0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
+// camp rings and glowing runes
+camp(1150,495,82,'#a562d7');camp(840,745,64,'#64d6b4');camp(1530,970,85,'#d7a348');camp(550,885,72,'#d7a348');
+// base platforms
+base(250,1370,'blue');base(2180,220,'red');
+// lane marker flags
+for(let i=0;i<lane.length;i++){let p=lane[i];if(i===0||i===lane.length-1)continue;ctx.fillStyle='#dfc987';ctx.globalAlpha=.24;ctx.beginPath();ctx.arc(p.x,p.y,5,0,7);ctx.fill();ctx.globalAlpha=1}
+}
+function drawTree(x,y,s,v){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#101d19';ctx.beginPath();ctx.ellipse(6,11,26,13,0,0,7);ctx.fill();ctx.fillStyle=['#294638','#31513d','#38583e','#294c44'][v];ctx.beginPath();ctx.arc(-9,-5,18,0,7);ctx.arc(10,-9,20,0,7);ctx.arc(1,-22,17,0,7);ctx.fill();ctx.fillStyle='#69805a66';ctx.beginPath();ctx.arc(-4,-21,8,0,7);ctx.fill();ctx.restore()}
+function camp(x,y,r,color){ctx.save();ctx.globalAlpha=.32;ctx.strokeStyle=color;ctx.lineWidth=2;ctx.setLineDash([6,7]);ctx.beginPath();ctx.arc(x,y,r,0,7);ctx.stroke();ctx.setLineDash([]);ctx.globalAlpha=.14;ctx.fillStyle=color;ctx.beginPath();ctx.arc(x,y,r-4,0,7);ctx.fill();ctx.globalAlpha=1;ctx.restore()}
+function base(x,y,team){ctx.save();ctx.translate(x,y);let c=team==='blue'?'#6bd4cf':'#f17673';ctx.globalAlpha=.22;ctx.fillStyle=c;ctx.beginPath();ctx.arc(0,0,95,0,7);ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle=c;ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,70,0,7);ctx.stroke();ctx.fillStyle='#253432';ctx.beginPath();ctx.arc(0,0,46,0,7);ctx.fill();ctx.fillStyle='#d5bc76';ctx.beginPath();for(let i=0;i<8;i++){let a=i*Math.PI/4;ctx.lineTo(Math.cos(a)*38,Math.sin(a)*38)}ctx.closePath();ctx.fill();ctx.fillStyle='#fff0bb';ctx.beginPath();ctx.arc(0,0,17,0,7);ctx.fill();ctx.restore()}

