function base(x,y,team){ctx.save();ctx.translate(x,y);let c=team==='blue'?'#6bd4cf':'#f17673';ctx.globalAlpha=.22;ctx.fillStyle=c;ctx.beginPath();ctx.arc(0,0,95,0,7);ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle=c;ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,70,0,7);ctx.stroke();ctx.fillStyle='#253432';ctx.beginPath();ctx.arc(0,0,46,0,7);ctx.fill();ctx.fillStyle='#d5bc76';ctx.beginPath();for(let i=0;i<8;i++){let a=i*Math.PI/4;ctx.lineTo(Math.cos(a)*38,Math.sin(a)*38)}ctx.closePath();ctx.fill();ctx.fillStyle='#fff0bb';ctx.beginPath();ctx.arc(0,0,17,0,7);ctx.fill();ctx.restore()}
function drawTower(t){if(t.dead)return;ctx.save();ctx.translate(t.x,t.y);ctx.fillStyle='#171d1c';ctx.beginPath();ctx.ellipse(0,12,43,22,0,0,7);ctx.fill();ctx.fillStyle='#573f3c';ctx.beginPath();ctx.moveTo(-26,12);ctx.lineTo(-19,-24);ctx.lineTo(-10,-39);ctx.lineTo(10,-39);ctx.lineTo(21,-22);ctx.lineTo(28,12);ctx.closePath();ctx.fill();ctx.fillStyle='#8c5549';ctx.beginPath();ctx.moveTo(-19,-23);ctx.lineTo(-12,-47);ctx.lineTo(12,-47);ctx.lineTo(21,-23);ctx.closePath();ctx.fill();ctx.fillStyle='#ffb08a';ctx.shadowColor='#ff6c54';ctx.shadowBlur=15;ctx.beginPath();ctx.arc(0,-29,7,0,7);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#ce8b6a';ctx.lineWidth=3;for(let i=-1;i<=1;i++){ctx.beginPath();ctx.moveTo(i*13,-11);ctx.lineTo(i*13,8);ctx.stroke()}ctx.restore();bar(t.x,t.y-57,70,t.hp/t.max,'#ec766e')}
function drawCore(c){if(c.dead)return;ctx.save();ctx.translate(c.x,c.y);ctx.rotate(gameTime*.18);ctx.fillStyle='#281e2a';ctx.beginPath();for(let i=0;i<8;i++){let a=i*Math.PI/4;ctx.lineTo(Math.cos(a)*48,Math.sin(a)*48)}ctx.closePath();ctx.fill();ctx.strokeStyle='#f38b7c';ctx.lineWidth=3;ctx.stroke();ctx.shadowColor='#ff766b';ctx.shadowBlur=24;ctx.fillStyle='#ffb899';ctx.beginPath();ctx.arc(0,0,19,0,7);ctx.fill();ctx.shadowBlur=0;ctx.restore();bar(c.x,c.y-65,82,c.hp/c.max,'#f07870')}
function bar(x,y,w,p,color){ctx.fillStyle='#091311';ctx.fillRect(x-w/2,y,w,5);ctx.fillStyle=color;ctx.fillRect(x-w/2+1,y+1,(w-2)*clamp(p,0,1),3)}
function drawPlayer(){if(!player.alive)return;const p=player;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.heading);if(p.shield>0){ctx.strokeStyle='#8edbf3';ctx.globalAlpha=.55+.3*Math.sin(gameTime*8);ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,29,0,7);ctx.stroke();ctx.globalAlpha=1}
ctx.fillStyle='#0c1918';ctx.beginPath();ctx.ellipse(0,11,17,9,0,0,7);ctx.fill();ctx.fillStyle='#61b7a5';ctx.beginPath();ctx.moveTo(-12,6);ctx.lineTo(-10,-7);ctx.lineTo(-6,-14);ctx.lineTo(9,-12);ctx.lineTo(14,3);ctx.lineTo(8,12);ctx.lineTo(-9,12);ctx.closePath();ctx.fill();ctx.fillStyle='#d8c590';ctx.beginPath();ctx.arc(0,-15,8,0,7);ctx.fill();ctx.fillStyle='#b8d7c7';ctx.beginPath();ctx.arc(0,-16,7,Math.PI,0);ctx.fill();ctx.fillStyle='#e3c36f';ctx.fillRect(-2,-24,4,8);ctx.strokeStyle='#e5c779';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(8,-5);ctx.lineTo(15,-20);ctx.stroke();ctx.fillStyle='#e1ca82';ctx.beginPath();ctx.arc(15,-21,3,0,7);ctx.fill();if(p.attackAnim>0){ctx.strokeStyle='#fff1bc';ctx.globalAlpha=p.attackAnim*2;ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,0,32,-.8,.7);ctx.stroke()}ctx.restore();bar(p.x,p.y-37,48,p.hp/p.max,'#61dfa9');if(p.hp<p.max)bar(p.x,p.y-32,40,p.hp/p.max,'#55d59f')}
function drawEntity(e){if(e.dead)return;ctx.save();ctx.translate(e.x,e.y);ctx.fillStyle='#07110f66';ctx.beginPath();ctx.ellipse(1,e.radius*.68,e.radius*1.25,e.radius*.56,0,0,7);ctx.fill();if(e.type==='minion'){ctx.fillStyle=e.team==='blue'?'#4c9f96':'#bd655e';ctx.beginPath();ctx.arc(0,0,e.radius,0,7);ctx.fill();ctx.fillStyle=e.team==='blue'?'#a1e2c7':'#f2b0a1';ctx.beginPath();ctx.arc(0,-3,5,0,7);ctx.fill();ctx.strokeStyle='#c2b98b';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(5,1);ctx.lineTo(13,-6);ctx.stroke()}
else if(e.type==='golem'){ctx.fillStyle='#96764c';ctx.beginPath();ctx.moveTo(-e.radius,-8);ctx.lineTo(-e.radius*.65,-e.radius);ctx.lineTo(7,-e.radius*1.1);ctx.lineTo(e.radius,-8);ctx.lineTo(e.radius*.7,e.radius*.65);ctx.lineTo(-e.radius*.8,e.radius*.65);ctx.closePath();ctx.fill();ctx.fillStyle='#edc278';ctx.shadowColor='#ffad59';ctx.shadowBlur=8;ctx.fillRect(-7,-8,4,4);ctx.fillRect(4,-8,4,4);ctx.shadowBlur=0}
else{ctx.fillStyle='#74528c';ctx.beginPath();ctx.ellipse(0,0,13,16,0,0,7);ctx.fill();ctx.fillStyle='#f1c2ff';ctx.shadowColor='#df82ff';ctx.shadowBlur=9;ctx.beginPath();ctx.arc(-4,-3,2,0,7);ctx.arc(4,-3,2,0,7);ctx.fill();ctx.shadowBlur=0}
ctx.restore();if(e.hp<e.max)bar(e.x,e.y-e.radius-10,32,e.hp/e.max,e.team==='blue'?'#71d9ba':e.team==='red'?'#ed7774':'#c37ce0')}
function draw(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,vw,vh);let scale=Math.min(vw/1050,vh/680);scale=Math.max(.56,scale);const worldW=vw/scale,worldH=vh/scale;camera.x=clamp(player.x,worldW/2,W-worldW/2);camera.y=clamp(player.y,worldH/2,H-worldH/2);ctx.save();ctx.scale(scale,scale);ctx.translate(worldW/2-camera.x,worldH/2-camera.y);drawGround();drawTower(tower);drawCore(core);for(const d of decals){ctx.globalAlpha=d.life/d.max;ctx.fillStyle=d.color;ctx.beginPath();ctx.arc(d.x,d.y,d.r*(1.15-d.life/d.max),0,7);ctx.fill()}ctx.globalAlpha=1;for(const e of entities)drawEntity(e);for(const p of projectiles)drawProjectile(p);drawPlayer();for(const p of particles){ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,7);ctx.fill()}ctx.globalAlpha=1;ctx.restore();drawMini()}
function drawProjectile(p){ctx.save();ctx.shadowColor=p.color;ctx.shadowBlur=13;ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,7);ctx.fill();ctx.restore()}
function drawMini(){const w=mini.width,h=mini.height;mctx.clearRect(0,0,w,h);mctx.fillStyle='#1b3027';mctx.fillRect(0,0,w,h);mctx.beginPath();mctx.moveTo(lane[0].x/W*w,lane[0].y/H*h);for(let p of lane)mctx.lineTo(p.x/W*w,p.y/H*h);mctx.lineWidth=12;mctx.strokeStyle='#746a4e';mctx.stroke();mctx.fillStyle='#65d9ce';mctx.beginPath();mctx.arc(250/W*w,1370/H*h,10,0,7);mctx.fill();mctx.fillStyle='#f07470';mctx.beginPath();mctx.arc(2180/W*w,220/H*h,10,0,7);mctx.fill();if(!tower.dead){mctx.fillStyle='#f28a77';mctx.beginPath();mctx.arc(tower.x/W*w,tower.y/H*h,4,0,7);mctx.fill()}mctx.fillStyle='#7edbb9';mctx.beginPath();mctx.arc(player.x/W*w,player.y/H*h,4,0,7);mctx.fill();for(const e of entities){if(e.dead||e.type==='minion')continue;mctx.fillStyle=e.team==='neutral'?'#b67ce0':'#ed8179';mctx.beginPath();mctx.arc(e.x/W*w,e.y/H*h,2.5,0,7);mctx.fill()}}

