function drawMini(){const w=mini.width,h=mini.height;mctx.clearRect(0,0,w,h);mctx.fillStyle='#1b3027';mctx.fillRect(0,0,w,h);mctx.beginPath();mctx.moveTo(lane[0].x/W*w,lane[0].y/H*h);for(let p of lane)mctx.lineTo(p.x/W*w,p.y/H*h);mctx.lineWidth=12;mctx.strokeStyle='#746a4e';mctx.stroke();mctx.fillStyle='#65d9ce';mctx.beginPath();mctx.arc(250/W*w,1370/H*h,10,0,7);mctx.fill();mctx.fillStyle='#f07470';mctx.beginPath();mctx.arc(2180/W*w,220/H*h,10,0,7);mctx.fill();if(!tower.dead){mctx.fillStyle='#f28a77';mctx.beginPath();mctx.arc(tower.x/W*w,tower.y/H*h,4,0,7);mctx.fill()}mctx.fillStyle='#7edbb9';mctx.beginPath();mctx.arc(player.x/W*w,player.y/H*h,4,0,7);mctx.fill();for(const e of entities){if(e.dead||e.type==='minion')continue;mctx.fillStyle=e.team==='neutral'?'#b67ce0':'#ed8179';mctx.beginPath();mctx.arc(e.x/W*w,e.y/H*h,2.5,0,7);mctx.fill()}}
function nearestEnemy(x,y,max=Infinity,includeStructure=false){let best=null,bd=max;for(const e of entities){if(e.dead||e.team==='blue')continue;const d=Math.hypot(x-e.x,y-e.y);if(d<bd){best=e;bd=d}}if(includeStructure&&!tower.dead){const d=Math.hypot(x-tower.x,y-tower.y);if(d<bd&&d<220)best=tower}if(includeStructure&&tower.dead&&!core.dead){const d=Math.hypot(x-core.x,y-core.y);if(d<bd&&d<220)best=core}return best}
function damage(target,amount,source='player'){if(!target||target.dead)return;let n=amount;if(target===player){if(player.shield){const a=Math.min(player.shield,n);player.shield-=a;n-=a}player.hp-=n;if(player.hp<=0)playerDeath();return}target.hp-=n;target.hurt=.16;if(target.hp<=0){target.hp=0;target.dead=true;const isEnemy=target.team==='red',isNeutral=target.team==='neutral';if(isEnemy){kills++;allyScore++;gold+=target.worth||25;questKills++;gainXP(28);showToast('Düşman alt edildi · +'+(target.worth||25)+' altın')}else if(isNeutral){gold+=target.worth;gainXP(target.worth*.7);showToast(target.type==='golem'?'Kadim golem avlandı · +95 altın':'Gölge avlandı · +62 altın')}if(target===tower){tower.dead=true;gold+=250;gainXP(180);showToast('Alacakaranlık Kulesi yıkıldı! +250 altın');$('towerStatus').textContent='Kule yıkıldı · Çekirdeğe ilerle!'}if(target===core){core.dead=true;gameOver=true;showEnd(true)}}}
function gainXP(n){xp+=n;while(xp>=xpNeed){xp-=xpNeed;level++;xpNeed=Math.round(xpNeed*1.35);player.max+=75;player.hp=Math.min(player.max,player.hp+100);player.damage+=7;player.maxMana+=25;player.mana=player.maxMana;showToast('Seviye '+level+'! Güçlendin.')}}
function playerDeath(){if(!player.alive)return;player.alive=false;player.respawn=6;deaths++;enemyScore++;gold=Math.max(0,gold-60);autoTarget=null;showToast('Düştün! 6 saniyede üsse dönüyorsun')}
function showToast(t){const el=$('toast');el.textContent=t;el.classList.add('show');clearTimeout(showToast.t);showToast.t=setTimeout(()=>el.classList.remove('show'),2100)}
function showEnd(win){$('overlay').classList.remove('hidden');$('playBtn').textContent=win?'TEKRAR OYNA':'YENİDEN DENE';$('overlay').querySelector('h1').textContent=win?'VADİ KURTULDU':'YOLCU DÜŞTÜ';$('overlay').querySelector('.sub').textContent=win?'KIZIL ÇEKİRDEK YOK EDİLDİ':'BU SADECE BAŞLANGIÇ';$('overlay').querySelector('p').textContent=win?'Takımın Kırık Taç Vadisi’ni özgürleştirdi. Bu zafer senin!':'Vadinin karanlığı seni yendi; yeniden doğ ve savaşa devam et.'}
function fireAt(target,damageAmt,speed,color,radius=6){if(!target)return;const a=Math.atan2(target.y-player.y,target.x-player.x);player.heading=a;projectiles.push({x:player.x,y:player.y-4,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,target,damage:damageAmt,color,r:radius,life:1.2,team:'blue'})}
function attack(){if(!player.alive||attackTimer>0)return;let t=autoTarget;if(!t||t.dead||dist(player,t)>player.range+60)t=nearestEnemy(mouse.wx||player.x,mouse.wy||player.y,300,true)||nearestEnemy(player.x,player.y,player.range+180,true);if(!t)return;let d=Math.hypot(t.x-player.x,t.y-player.y);if(d>player.range){if(t===tower||t===core){showToast('Yapıya yaklaşman gerekiyor');return}return}autoTarget=t;attackTimer=.72;player.attackAnim=.22;fireAt(t,player.damage,570,'#f3d37d',5)}
function castSpell(k){if(!player.alive||cast[k]>0)return;let cost={q:45,w:55,e:40,r:110}[k];if(player.mana<cost){showToast('Yeterli mana yok');return}player.mana-=cost;
if(k==='q'){let t=autoTarget&&!autoTarget.dead?autoTarget:nearestEnemy(mouse.wx,mouse.wy,380,true);if(!t){player.mana+=cost;showToast('Yıldız oku için hedef seç');return}fireAt(t,110+level*18,720,'#82e5ed',8);cast.q=5.5;showToast('✧ Yıldız oku!')}
if(k==='w'){player.shield=210+level*35;player.hp=Math.min(player.max,player.hp+65);cast.w=10;particles.push({x:player.x,y:player.y,life:.65,max:.65,color:'#86dbeb',r:42});showToast('◈ Ay kalkanı · +65 sağlık')}
if(k==='e'){let dx=mouse.wx-player.x,dy=mouse.wy-player.y,len=Math.hypot(dx,dy)||1;player.x=clamp(player.x+dx/len*185,40,W-40);player.y=clamp(player.y+dy/len*185,40,H-40);player.heading=Math.atan2(dy,dx);cast.e=8;particles.push({x:player.x,y:player.y,life:.5,max:.5,color:'#9ee9cf',r:35})}
if(k==='r'){let x=mouse.wx||player.x,y=mouse.wy||player.y;if(Math.hypot(x-player.x,y-player.y)>430){x=player.x+(x-player.x)*430/Math.hypot(x-player.x,y-player.y);y=player.y+(y-player.y)*430/Math.hypot(x-player.x,y-player.y)}particles.push({x,y,life:.6,max:.6,color:'#f5c46b',r:175});for(const e of entities)if(!e.dead&&e.team!=='blue'&&Math.hypot(x-e.x,y-e.y)<180)damage(e,260+level*42);if(!tower.dead&&Math.hypot(x-tower.x,y-tower.y)<180)damage(tower,220+level*30);if(tower.dead&&!core.dead&&Math.hypot(x-core.x,y-core.y)<180)damage(core,220+level*30);cast.r=32;showToast('☄ KOZMİK PATLAMA!')}
}

